import { useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./HomePage.css";

const socket = io("http://localhost:5000");

function HomePage() {

  const navigate = useNavigate();

  const [stats,setStats]=useState({

    totalOP:0,

    waiting:0,

    completed:0,

    confirmed:0

  });



  const fetchStats = async()=>{

    try{

      const res =
      await fetch(
        "http://localhost:5000/api/queue/all"
      );

      const data =
      await res.json();

      setStats({

        totalOP:
        data.length,

        waiting:
        data.filter(
          q =>
          q.status==="InQueue"
        ).length,

        completed:
        data.filter(
          q =>
          q.status==="Completed"
        ).length,

        confirmed:
        data.filter(
          q =>
          q.status==="Confirmed"
        ).length

      });

    }

    catch(err){

      console.log(err);

    }

  };



  useEffect(()=>{

    fetchStats();

    socket.on(
      "queueUpdated",
      fetchStats
    );

    return ()=>{

      socket.off(
        "queueUpdated"
      );

    };

  },[]);



  return(

<div className="home">

<nav className="navbar">

<h1 className="logo">

HealSync

</h1>

<button

className="admin-btn"

onClick={()=>
navigate(
"/admin"
)
}

>

Admin

</button>

</nav>



<section className="hero">

<div className="hero-left">

<div className="welcome-popup">

✨ Welcome to HealSync

</div>

<h2>

HealSync

</h2>

<p>

Real Time Patient Queue System

</p>

<button

className="login-btn"

onClick={()=>
navigate(
"/login"
)
}

>

Login

</button>

</div>



<div className="hero-right">

<div className="card">

<span>

🩺

</span>

<h3>

Total OP

</h3>

<h1>

{stats.totalOP}

</h1>

</div>



<div className="card">

<span>

⏳

</span>

<h3>

Waiting

</h3>

<h1>

{stats.waiting}

</h1>

</div>



<div className="card">

<span>

✅

</span>

<h3>

Confirmed

</h3>

<h1>

{stats.confirmed}

</h1>

</div>



<div className="card">

<span>

🏁

</span>

<h3>

Completed

</h3>

<h1>

{stats.completed}

</h1>

</div>

</div>

</section>

</div>

);

}

export default HomePage;
